      if (message.type === 'ui_event' && active && (eventId === 'mode_pawn' || eventId === 'mode_wall')) {
        selectedMode = eventId === 'mode_wall' ? 'wall' : 'pawn';
        return {scene, local_state: {mode:selectedMode,move_count:m.move_count,
